
/* SmartHR Dashboard Scoped CSS - Strictly isolated */
.dashboard-scope {
  --bs-body-bg: #fff;
  --bs-body-color: #3b3f5c;
  --bs-card-bg: #fff;
  --bs-card-color: #3b3f5c;
  --bs-card-border-color: #e8ebed;
  --bs-border-color: #e8ebed;
  --primary-transparent: #FEF1EB;
  --secondary-transparent: #EDF2F4;
  --success-transparent: #E8FAF0;
  --warning-transparent: #FFF9E9;
  --danger-transparent: #FAE7E7;
  --info-transparent: #EBF4FF;
  --pink-transparent: #FFEDF6;
  --light-transparent: #F9FAFE;
  --dark-transparent: #E8E9EA;
  --teal-transparent: #E6F9FF;
  --purple-transparent: #F7EEF9;
  --skyblue-transparent: #E9FAFE;
  --white-color: #fff;
  --border-color: #e8ebed;
  font-family: inherit;
  color: #3b3f5c;
  box-sizing: border-box;
}

.dashboard-scope *, .dashboard-scope *::before, .dashboard-scope *::after {
  box-sizing: border-box;
}

.dashboard-scope .card {
  background-color: var(--bs-card-bg, #ffffff);
  border: 1px solid var(--bs-card-border-color, #e8ebed);
  border-radius: 0.5rem;
  box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.05);
}

.dashboard-scope .card-header {
  background-color: #ffffff;
  border-bottom: 1px solid #e8ebed;
}

.dashboard-scope .card-footer {
  background-color: #ffffff;
  border-top: 1px solid #e8ebed;
}

.dashboard-scope .card-title {
  color: #212529;
  font-weight: 600;
}

.dashboard-scope h1, .dashboard-scope h2, .dashboard-scope h3, .dashboard-scope h4, .dashboard-scope h5, .dashboard-scope h6 {
  color: #212529;
}

.dashboard-scope a {
  text-decoration: none;
}

.dashboard-scope .table {
  --bs-table-bg: transparent;
}

