@charset "UTF-8";
/****** Utils ******/
@import url("https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,100;0,300;0,400;0,500;0,700;0,900;1,100;1,300;1,400;1,500;1,700;1,900&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Archivo:ital,wght@0,100..900;1,100..900&display=swap");
.dashboard-scope {
  --primary-transparent: #FEF1EB;
  --secondary-transparent: #EDF2F4;
  --success-transparent: #E8FAF0;
  --warning-transparent: #FFF9E9;
  --danger-transparent: #FAE7E7;
  --info-transparent: #EBF4FF;
  --pink-transparent: #FFEDF6;
  --light-transparent: #F9FAFE;
  --dark-transparent: #E8E9EA;
  --teal-transparent: #E6F9FF;
  --purple-transparent: #F7EEF9;
  --skyblue-transparent: #E9FAFE;
  --primary-linear-gradient: linear-gradient(270deg, rgba(242, 101, 34, 0.3) 0%, #FFFFFF 100%);
  --warning-linear-gradient: linear-gradient(270deg, rgba(255, 193, 7, 0.3) 0%, #FFFFFF 100%);
  --success-linear-gradient: linear-gradient(270deg, rgba(3, 201, 90, 0.3) 0%, #FFFFFF 100%);
  --info-linear-gradient: linear-gradient(270deg, rgba(27, 132, 255, 0.3) 0%, #FFFFFF 100%);
  --white-color: #fff;
  --border-color: #ededed;
  --success-gradient-100: linear-gradient(270deg, #DDFFEC 0%, #FFFFFF 100%);
  --danger-gradient-100: linear-gradient(270deg, #FFE5E5 0%, #FFFFFF 100%);
}

.dashboard-scope :root[data-theme=dark] {
  --primary-linear-gradient: linear-gradient(270deg, rgba(242, 101, 34, 0.3) 0%, #000 100%);
  --warning-linear-gradient: linear-gradient(270deg, rgba(255, 193, 7, 0.3) 0%, #000 100%);
  --success-linear-gradient: linear-gradient(270deg, rgba(3, 201, 90, 0.3) 0%, #000 100%);
  --white-color: #111827;
  --border-color: rgba(255, 255, 255, 0.07);
}

/******* Base *******/
/****** Utils ******/
.dashboard-scope {
  font-family: "Roboto", sans-serif;
  font-size: 14px;
  color: #6B7280;
  line-height: 1.5;
  background-color: var(--bs-body-bg, #F8F9FA);
  overflow-y: auto;
  overflow-x: hidden;
}

:is(.dark, [data-theme="dark"], [data-theme-mode="dark"]) .dashboard-scope,
.dashboard-scope:is(.dark, [data-theme="dark"], [data-theme-mode="dark"]),
:is([data-theme="dark"], .dark) .dashboard-scope,
[data-theme-mode="dark"] .dashboard-scope,
[data-theme="dark"] .dashboard-scope,
.dark .dashboard-scope {
  background-color: #0b0f19 !important;
  color: #cbd5e1 !important;
  --bs-body-bg: #0b0f19 !important;
}

.dashboard-scope ::selection {
  background: #F26522;
  color: #FFF;
  text-shadow: none;
}

.dashboard-scope img {
  max-width: 100%;
  height: auto;
  vertical-align: middle;
}

.dashboard-scope * {
  outline: none;
}

.dashboard-scope button {
  -webkit-transition: all 0.5s ease;
  -ms-transition: all 0.5s ease;
  transition: all 0.5s ease;
}
.dashboard-scope button:focus {
  box-shadow: none !important;
}

.dashboard-scope p {
  margin-bottom: 20px;
}
.dashboard-scope p:last-child {
  margin-bottom: 0;
}

.dashboard-scope strong {
  font-weight: 700;
}

.dashboard-scope h1, .dashboard-scope .h1, .dashboard-scope h2, .dashboard-scope .h2, .dashboard-scope h3, .dashboard-scope .h3, .dashboard-scope h4, .dashboard-scope .h4, .dashboard-scope h5, .dashboard-scope .h5, .dashboard-scope h6, .dashboard-scope .h6 {
  color: #202C4B;
  font-family: "Roboto", sans-serif;
  font-weight: 700;
  margin-bottom: 0;
}

.dashboard-scope ol, .dashboard-scope ul {
  list-style: none;
  margin-block-end: 0;
  padding: 0;
}

.dashboard-scope ul {
  list-style: none;
}
.dashboard-scope ul.list-disc {
  list-style: disc;
