  margin-left: -1.25rem;
  position: relative;
  left: -10px;
  padding: 1px;
  top: -1px;
}
.dashboard-scope ul.list-icon > li i {
  font-size: 20px;
  top: 5px;
}
.dashboard-scope ul .btn-primary:not(:disabled):not(.disabled):active:focus, .dashboard-scope ul .btn-primary:not(:disabled):not(.disabled).active:focus {
